 Check(correct&&m.ScoreJournal.Count==awards.Count,"original placement awards use unique both-member pair IDs, stable pair color and TEAM PTS without individual credit; receipts="+awards.Count);Check(Enumerable.Range(0,4).All(i=>Math.Abs(totals[i]-m.series.total[i])<.001),"actual pair award deltas exactly reconstruct all four original series totals");Check(Enumerable.Range(0,4).All(i=>m.TryReadScoreCard(i,out string value,out string detail)&&value==m.series.total[i].ToString()&&detail.StartsWith("PTS · ",StringComparison.Ordinal)),"duplicate pair names retain independent typed card totals");}
 string saved,folder;bool had,restored;int errors,lastRound;readonly bool[] finishes=new bool[4];readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){checks++;log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);Write();}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("WifeEvidence");yield return SportsProbeScene.Ensure<WifeMatch>("TruckWifeCarrying");m=FindAnyObjectByType<WifeMatch>();yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;SportsCameraOptions.Set(false);m.AllBots();m.weather=1;Check(m.StartMatch(),"four physical all-AI pairs start");Time.timeScale=4;while(m.Phase==WifePhase.Countdown)yield return null;Check(m.pairs.All(p=>p.Carried&&p.driver.Powered&&!p.passenger.Powered),"real roof joint with powered driver and unpowered smaller partner");var first=m.pairs[0];first.driver.body.rotation=Quaternion.AngleAxis(80,Vector3.forward)*first.driver.body.rotation;float end=Time.realtimeSinceStartup+5;while(first.State==WifeState.Racing&&Time.realtimeSinceStartup<end)yield return null;Check(first.Drops==1&&!first.Carried,"excessive physical tilt dislodges the constrained partner once");var point=m.course.loopCircuit?m.course.Point(10):m.course.Surface(new Vector3(0,0,30));first.driver.body.position=point+Vector3.up*.6f;first.driver.body.rotation=Quaternion.identity;first.driver.body.linearVelocity=first.driver.body.angularVelocity=Vector3.zero;first.passenger.body.position=point+Vector3.right*2+Vector3.up*.7f;first.passenger.body.rotation=Quaternion.identity;first.passenger.body.linearVelocity=first.passenger.body.angularVelocity=Vector3.zero;end=Time.realtimeSinceStartup+8;while(first.State!=WifeState.Penalty&&Time.realtimeSinceStartup<end)yield return null;Check(first.State==WifeState.Penalty&&first.Carried,"stopped nearby pair retrieves with visible pickup and reattaches");var pickup=first.PickupOrigin;Check(first.driver.body.position.z<pickup.z+1&&first.Checkpoint==0,"retrieval never teleports driver forward or skips ordered gates");m.Pause();var p=first.passenger.body.position;float clock=m.Clock,penalty=first.PenaltyRemaining;yield return new WaitForSecondsRealtime(.15f);Check(p==first.passenger.body.position&&clock==m.Clock&&penalty==first.PenaltyRemaining,"pause preserves constrained passenger clock and penalty");m.Resume();Time.timeScale=4;yield return new WaitForSeconds(5.2f);Check(first.State==WifeState.Racing&&m.Clock-clock>=5,"fixed five-second penalty elapses while other pairs continue");m.SetupScreen();m.AllBots();m.option=1;for(int i=0;i<8;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);for(int i=0;i<4;i++)m.teams[i]="Same Pair";m.ScoreConfirmed+=awards.Add;Check(m.StartMatch(),"fresh complete mixed-difficulty series starts");bool awardCaptured=false;Time.timeScale=4;end=Time.realtimeSinceStartup+900;float next=0;bool swapped=false;while(!m.Finished&&Time.realtimeSinceStartup<end){if(!awardCaptured&&m.ScoreJournal.Count>0){yield return SportsScoreAcceptance.CaptureAward(m,Check,folder);awardCaptured=true;}if(m.Phase==WifePhase.RaceResult&&lastRound!=m.series.round){lastRound=m.series.round;for(int i=0;i<4;i++)finishes[i]|=m.pairs[i].State==WifeState.Finished;log.AppendLine("RACE "+lastRound+" ranks="+string.Join(",",m.series.ranks)+" drops="+string.Join(",",m.pairs.Select(pair=>pair.Drops)));}swapped|=m.Swapped;if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"CURRENT race="+m.series.round+" phase="+m.Phase+" clock="+m.Clock+" states="+string.Join(",",m.pairs.Select(pair=>pair.State+":"+pair.Checkpoint+":"+pair.driver.body.position.z.ToString("F0")+":"+pair.Drops))+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}
 VerifyAwards();Check(awardCaptured,"actual original pair placement feedback captured");if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder,slot=>m.ResultPlace(slot%4),slot=>(double?)m.series.total[slot%4],slot=>m.series.winner==slot%4);
 Check(m.Finished&&m.series.completed>=3&&m.series.winner>=0,"complete physical three-race series with authoritative winner");Check(finishes.All(value=>value),"all four pairs can finish together in carried state");Check(swapped&&m.DriverRole(0)==((m.series.completed-1)%2==0?0:4)&&m.PassengerRole(0)==((m.series.completed-1)%2==0?4:0),"automatic between-race role swaps preserve identity indices across ordinary and extra races");log.AppendLine("MATCH races="+m.series.completed+" winner="+m.series.winner+" points="+string.Join(",",m.series.total)+" ERRORS="+errors+". Actual NWH/PhysX, controlled drop/retrieval reproduction and AI; no human/hardware validation.");m.SetupScreen();Check(m.StartMatch()&&m.series.completed==0&&m.ScoreJournal.Count==0&&m.series.total.All(value=>value==0),"rematch clears original pair totals and confirmed-score journal");m.SetupScreen();log.AppendLine("CHECKS="+checks+" ERRORS="+errors);File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("WIFE_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){if(m!=null)m.ScoreConfirmed-=awards.Add;Restore();preferences?.Dispose();SportsParticipantRegistry.ForgetCache();}
